export default ({g,t,p,low})=>{let c=p[0],scale=c>10?1-(c-10)/10*.28:1;cell(g,true,-1,scale);let inward=c<10;for(let i=0;i<(low?8:16);i++){let a=i*Math.PI/8,phase=(t*.18+i*.07)% .5,goIn=c===10?i%2===0:inward,r=goIn?1.55-phase*1.6:.75+phase*1.6;g.sphere(Math.cos(a)*r,Math.sin(a)*r*.75,0,.035,C.blue)}if(c!==10)g.arrow(inward?[1.6,0,0]:[.8,0,0],inward?[.8,0,0]:[1.6,0,0],C.blue);return[read('Outside concentration','बाहरी सान्द्रता',c,'g/L'),read('Initial inside concentration','प्रारम्भिक भीतरी सान्द्रता',10,'g/L'),{label:b('Net water movement','जल का शुद्ध गमन'),value:c<10?b('Into the cell','कोशिका के अन्दर'):c>10?b('Out of the cell','कोशिका के बाहर'):b('No net movement initially','आरम्भ में शुद्ध गमन नहीं')}];};
